    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, so we need to pop argument types
        int i = 1;
        while (descriptor.charAt(i) != ')') {
            i = popType(descriptor, i);
        }
    } else {
        // It's a type descriptor, so we pop the single type
        popType(descriptor, 0);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
        case 'F':
            // These types occupy one slot
            index++;
            break;
        case 'J':
        case 'D':
            // These types occupy two slots
            index++;
            break;
        case 'L':
            // Object type, skip to the end of the descriptor for this object
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            index++; // Skip the ';'
            break;
        case '[':
            // Array type, skip to the type of the array elements
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

