    long totalSum = 0;
    for (int bound : bounds) {
        totalSum += bound;
    }

    long runningSum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffixSum.add(0, (int) runningSum);
    }

    return new Pair<>(suffixSum, totalSum);
}

